import{d as c,C as t,o as u,c as p,j as a,a as s,E as o,a3 as b}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"道德经第七十章","description":"由易知易行与莫能知行的反差，读言有宗、事有君及被褐怀玉的内守。","frontmatter":{"title":"道德经第七十章","description":"由易知易行与莫能知行的反差，读言有宗、事有君及被褐怀玉的内守。","category":"guide","aliases":["道德经第七十章","老子第七十章","dao de jing chapter 70"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-70.md","filePath":"daoism/dao-de-jing/chapter-70.md","lastUpdated":1794189804000}'),g={name:"daoism/dao-de-jing/chapter-70.md"},_=c({...g,setup(m){const n=[{id:"easy-to-understand-and-practice",label:"吾言甚易知，甚易行",showLabel:!0,sentences:[["吾言甚",{text:"易",glossary:"yi"},{text:"知",glossary:"zhi"},"，甚",{text:"易",glossary:"yi"},"行。"]],note:["【白话】我的话很容易理解，也很容易实行。依本章王注，它所依的认识与行动，不在于不断向外追逐或增加造作。","【王弼注择要】「可不出户窥牖而知」，注由此说明易知；又以「无为而成」说明易行。","【读法】可与第四十七章不出户、第四十八章无为相参。容易说的是根本取向简要，不是保证具体处境中不用学习、判断与练习。"]},{id:"why-understanding-is-obscured",label:"天下莫能知，莫能行",showLabel:!0,sentences:[["天下莫能",{text:"知",glossary:"zhi"},"，莫能行。"]],note:["【白话】可是天下却没有人能够真正理解，也没有人能够实行。经文用强烈的反差，指出易知易行的道理仍难被落实。","【王弼注择要】所据先以躁欲解释难知，又说「迷于荣利，故曰莫之能行也」，把难行联系到对荣名与利益的迷逐。","【读法】莫能的语势用于突出章旨，不当作对全部人的实证统计。所据前注作或于躁欲，本页说明其解释方向，不擅改字后作引文。"]},{id:"root-and-governing-principle",label:"言有宗，事有君",showLabel:!0,sentences:[["言有",{text:"宗",glossary:"zong"},"，事有",{text:"君",glossary:"jun"},"。"]],note:["【白话】言论有它的宗本，行事有它的主导。依王弼解释，这个宗与君都指向万物所依的根本，而非零散的说法和动作。","【王弼注择要】「宗，万物之宗也。君，万物之主也。」注用万物之宗、主来说明统摄之意。","【读法】不能只译成说话总有来历、做事总有上司。回看本章，易知易行与莫能知行的分歧，就与能否识得这一宗本有关。"]},{id:"not-knowing-the-root",label:"夫唯无知，是以不我知",showLabel:!0,sentences:[["夫唯",{text:"无知",glossary:"wuzhi"},"，是以不我",{text:"知",glossary:"zhi"},"。"]],note:["【白话】正因为人们不了解这个宗本，所以不能了解我所说所行的道。不我知就是不知我，是否定句中宾语前置的表达。","【王弼注择要】「以其言有宗、事有君之故」，注又说「故有知之人不得不知之也」，承接上句说明识其宗主与知我的关系。","【读法】本句无知是不了解，并非第三章少机巧、不事智巧的义项。也不要把不了解整理成一种值得自夸的状态，而忽略所说的认识问题。"]},{id:"few-understand-and-follow",label:"知我者希，则我者贵",showLabel:!0,sentences:[[{text:"知",glossary:"zhi"},"我者",{text:"希",glossary:"xi"},"，",{text:"则",glossary:"ze"},"我者",{text:"贵",glossary:"gui"},"。"]],note:["【白话】了解我的人很少，能够取法于我的人可贵而难得。希在这里是稀少，则是以之为法，不作那么解释。","【王弼注择要】「唯深，故知之者希也。」又说「知我益希，我亦无匹」，从道之深与无匹来说明其少知与可贵。","【读法】前面的白话先呈取法者可贵的句面读法，再列王注我亦无匹的解释重心，不把两者悄悄混作同一逐字翻译。少人理解本身，也不能作为一种说法正确的证据。"]},{id:"plain-clothes-and-jade",label:"圣人被褐而怀玉",showLabel:!0,sentences:[["是以圣人",{text:"被",glossary:"pi"},{text:"褐",glossary:"he"},"而",{text:"怀玉",glossary:"huaiyu"},"。"]],note:["【白话】因此，圣人身穿粗布衣，怀中却藏着美玉。外在形貌可以朴素平常，内在仍守护着可贵而真实的品质。","【王弼注择要】「被褐者，同其尘。怀玉者，宝其真也。」后文又说「同尘而不殊，怀玉而不渝」，解释不刻意显异而不改变内守。","【读法】被通披，读 pī；褐为粗布衣。譬喻同时有外朴与内真两面，不因穿得朴素、处境困顿或不被理解，就自动推定一个人怀玉。"]}],r=[{id:"yi",term:"易",sense:1},{id:"zhi",term:"知",sense:2,pinyin:["zhī"]},{id:"zong",term:"宗",sense:1},{id:"jun",term:"君",sense:1},{id:"wuzhi",term:"无知",sense:2},{id:"xi",term:"希",sense:2},{id:"ze",term:"则",sense:1},{id:"gui",term:"贵",sense:4},{id:"pi",term:"被",sense:2,pinyin:["pī"]},{id:"he",term:"褐",sense:1},{id:"huaiyu",term:"怀玉",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),p("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第七十章",tabindex:"-1"},[s("道德经第七十章 "),a("a",{class:"header-anchor",href:"#道德经第七十章","aria-label":'Permalink to "道德经第七十章"'},"​")],-1)),o(i,{title:"说得易知易行，为什么仍然不被理解",summary:"本章先摆出易知易行与莫能知行的反差，再指出言论有宗本、行事有统摄。结尾以知者少、取法者可贵与被褐怀玉收束：所守的真不必外露为显赫形貌。王弼从躁欲、荣利解释人为何难知难行。",points:[{label:"先读",text:"易知易行先说所依的根本简要，再看躁欲、荣利怎样使理解与践行受阻。"},{label:"再辨",text:"宗与君指宗本和主导，不只是一句话有出处、一件事有上级。"},{label:"后看",text:"希取稀少，则取法；被褐与怀玉以外在朴素、内守其真合读。"}],hint:"知在本章读 zhī，希读 xī，取稀少义；则读 zé，作取法；被褐读 pī hè，被通披。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:n,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"吾言甚易知，甚易行。天下莫能知，莫能行。",tone:"先看反差",guide:"王注从躁欲、荣利解释阻碍，帮助读者追问知行何以脱节。"},{text:"言有宗，事有君。",tone:"把零散言行连到宗本",guide:"宗与君不是外在身份，而是所依的根本与统摄。"},{text:"是以圣人被褐而怀玉。",tone:"不显异而守其真",guide:"外在与众同尘，内在不渝；两面合读，才不只剩怀才不遇的自我想象。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:r}),e[4]||(e[4]=b("",15))])}}});export{f as __pageData,_ as default};
